def is_pow2(n):
    return n > 0 and (n & (n-1)) == 0

solutions = set()
N = 3000

for a in range(1, N+1):
    for b in range(a, N+1):
        ab = a * b
        if a == 1:
            continue
        max_x_val = b * (a - 1)
        pow2x = 1
        while pow2x <= max_x_val:
            c = ab - pow2x
            if c >= b and c >= 1:
                if is_pow2(b * c - a) and is_pow2(c * a - b):
                    solutions.add((a, b, c))
            pow2x *= 2

for s in sorted(solutions):
    a,b,c = s
    print(f"({a},{b},{c}): ab-c={a*b-c}, bc-a={b*c-a}, ca-b={c*a-b}")
EOF
